   493|function showImportResults(r){var el=document.getElementById('importResults');el.style.display='block';var s='<div style="margin-bottom:10px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:12px"><span class="badge '+(r.dryRun?'amber':'green')+'">'+(r.dryRun?'DRY RUN':'IMPORTED')+'</span> <b>'+r.total+'</b> rows: <span style="color:var(--good);font-weight:600">'+r.created+' created</span>, <span style="color:var(--blue);font-weight:600">'+r.updated+' updated</span>, <span style="color:var(--alert);font-weight:600">'+r.errors+' errors</span>';if(r.invited>0)s+=', <span style="color:var(--orange);font-weight:600">'+r.invited+' invited</span>';s+='</div>';document.getElementById('importSummary').innerHTML=s;var h='<table><thead><tr><th>Row</th><th>Phone</th><th>Student</th><th>Status</th><th>Message</th></tr></thead><tbody>';for(var i=0;i<r.results.length;i++){var row=r.results[i];var bg=row.status==='created'?'green':row.status==='updated'?'blue':row.status==='skipped'?'amber':'red';h+='<tr><td>'+row.row+'</td><td>'+(row.phone||'')+'</td><td>'+(row.student||'')+'</td><td><span class="badge '+bg+'">'+row.status+'</span></td><td>'+(row.message||'')+'</td></tr>'}h+='</tbody></table>';document.getElementById('importTableWrap').innerHTML=h}
